// ── Asistente IA (solo admin) ──────────────────────────────────────────────
// El asistente se llama Mártin y su cara es el tornillo mecánico. Se consulta
// desde un globo flotante (abajo a la derecha) y cada chat queda guardado en
// la pantalla "Asistente IA", que es solo de lectura: un chat guardado no se
// puede continuar (el servidor también lo impide). Mártin lee las respuestas
// en voz alta y mueve la boca, salvo que se lo silencie con el parlante.
// El servidor decide todo (rol, límites, datos); acá solo se muestra. El texto
// del modelo se ESCAPA completo antes de darle formato (negritas, listas,
// tablas): nunca se inserta HTML, links ni imágenes que vengan de la respuesta.
let _iaConv=0, _iaEnviando=false, _iaHistSel=null, _iaHistTimer=null;
let _iaVozNatural=false, _iaAudio=null, _iaAudioCtrl=null, _iaAudioCtx=null, _iaAnalizador=null, _iaVozAviso=false;
let _iaVoz, _iaMudoMem=null, _iaVozSesion=0, _iaVozCola=[], _iaBocaTimer=null, _iaBocaImgs=[], _iaBocaPaso=0;
// El tornillo mecánico: la imagen entera (globo) y la cara (avatar de los mensajes).
const IA_MASCOTA='data:image/png;base64,';
const IA_CARA='data:image/png;base64,';
// Boca entreabierta y abierta, para cuando Mártin habla.
const IA_MASCOTA_HABLA=['data:image/png;base64,','data:image/png;base64,'];
const IA_CARA_HABLA=['data:image/png;base64,','data:image/png;base64,'];
const IA_SUGERENCIAS=['¿Qué OT están atrasadas?','¿Qué materiales están bajo el stock mínimo?','Haceme un resumen general del taller','¿Qué OT vencen esta semana?'];
const IA_SVG={
  x:'<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M4 4l8 8M12 4l-8 8"/></svg>',
  nuevo:'<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M8 3.5v9M3.5 8h9"/></svg>',
  borrar:'<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2.5 4.5h11M6 4.5V3h4v1.5M4 4.5l.7 8.6a1 1 0 0 0 1 .9h4.6a1 1 0 0 0 1-.9l.7-8.6M6.7 7v4.5M9.3 7v4.5"/></svg>',
  hist:'<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2.5 8a5.5 5.5 0 1 0 1.6-3.9"/><path d="M2.5 2.5v2.5H5"/><path d="M8 5.2V8l2 1.3"/></svg>',
  voz:'<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2.5 6h2.2L8 3.3v9.4L4.7 10H2.5z"/><path d="M10.6 5.6a3.4 3.4 0 0 1 0 4.8M12.6 3.8a6 6 0 0 1 0 8.4"/></svg>',
  mudo:'<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2.5 6h2.2L8 3.3v9.4L4.7 10H2.5z"/><path d="M10.5 6l3.5 4M14 6l-3.5 4"/></svg>',
  enviar:'<svg viewBox="0 0 16 16" fill="currentColor"><path d="M2.2 2.3a.6.6 0 0 1 .7-.1l11 5.3a.6.6 0 0 1 0 1L2.9 13.8a.6.6 0 0 1-.8-.7L3.4 8 2.1 2.9a.6.6 0 0 1 .1-.6zm2.3 6.3l-.9 3.6L11.9 8 3.6 3.8l.9 3.6H8a.6.6 0 0 1 0 1.2z"/></svg>'
};
function _iaEsc(t){return String(t==null?'':t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function _iaInline(t){return t.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');}
function _iaMarkdown(txt){
  const L=_iaEsc(txt).split(/\r?\n/), esTabla=l=>/^\s*\|.*\|\s*$/.test(l), esUl=l=>/^\s*[-*•]\s+/.test(l), esOl=l=>/^\s*\d+[.)]\s+/.test(l), esTit=l=>/^\s*#{1,6}\s+/.test(l);
  let h='', i=0;
  while(i<L.length){
    const l=L[i];
    if(esTabla(l)){
      const filas=[]; while(i<L.length&&esTabla(L[i])) filas.push(L[i++]);
      const sep=filas.length>1&&/^[\s|:\-]+$/.test(filas[1]);
      h+='<table>'+filas.map((f,k)=>{
        if(sep&&k===1) return '';
        const tag=sep&&k===0?'th':'td';
        return '<tr>'+f.trim().replace(/^\||\|$/g,'').split('|').map(c=>'<'+tag+'>'+_iaInline(c.trim())+'</'+tag+'>').join('')+'</tr>';
      }).join('')+'</table>';
    } else if(esUl(l)){
      h+='<ul>'; while(i<L.length&&esUl(L[i])) h+='<li>'+_iaInline(L[i++].replace(/^\s*[-*•]\s+/,''))+'</li>'; h+='</ul>';
    } else if(esOl(l)){
      h+='<ol>'; while(i<L.length&&esOl(L[i])) h+='<li>'+_iaInline(L[i++].replace(/^\s*\d+[.)]\s+/,''))+'</li>'; h+='</ol>';
    } else if(esTit(l)){
      h+='<p><strong>'+_iaInline(l.replace(/^\s*#+\s+/,''))+'</strong></p>'; i++;
    } else if(!l.trim()){
      i++;
    } else {
      const par=[]; while(i<L.length&&L[i].trim()&&!esTabla(L[i])&&!esUl(L[i])&&!esOl(L[i])&&!esTit(L[i])) par.push(_iaInline(L[i++]));
      h+='<p>'+par.join('<br>')+'</p>';
    }
  }
  return h;
}
function _iaHerrHtml(herr){
  if(!herr||!herr.length) return '';
  return '<div class="ia-herr">'+herr.map(x=>'<span title="'+_iaEsc((x.detalle||'sin filtros')+(x.error?' · error: '+x.error:''))+'">'+_iaEsc(x.nombre)+(x.error?' ⚠':'')+'</span>').join('')+'</div>';
}
// '2026-10-22 13:15:38' -> '22/10/2026 13:15'
function _iaFecha(s){ const m=/^(\d{4})-(\d\d)-(\d\d)[ T](\d\d:\d\d)/.exec(s||''); return m?m[3]+'/'+m[2]+'/'+m[1]+' '+m[4]:(s||''); }
// rol: 'u' pregunta, 'a' respuesta, 'e' error. Preguntas y errores van como texto plano.
function _iaAgregar(box,rol,texto,herr,hora){
  const d=document.createElement('div'); d.className='ia-m '+rol;
  if(rol==='a') d.innerHTML=_iaMarkdown(texto)+_iaHerrHtml(herr); else d.textContent=texto;
  box.appendChild(rol==='a'?_iaConAvatar(d):d);
  if(hora){ const h=document.createElement('div'); h.className='ia-hora '+rol; h.textContent=_iaFecha(hora); box.appendChild(h); }
  box.scrollTop=box.scrollHeight;
  return d;
}
// Mensaje del asistente con la cara del tornillo al costado.
function _iaConAvatar(d){
  const f=document.createElement('div'); f.className='ia-fila';
  const av=document.createElement('img'); av.className='ia-av'; av.src=_iaFoto(false); av.alt='';
  f.appendChild(av); f.appendChild(d);
  return f;
}
function _iaEmpresa(){ const e=document.querySelector('.logo .emp'); return (e&&e.textContent.trim())||'el taller'; }

// ── Comandos de broma ───────────────────────────────────────────────────────
// Se escriben en el chat y se resuelven acá: no van al modelo ni al historial.
// /pirata cambia el estilo de las respuestas (el servidor recibe solo la clave
// del modo, de una lista cerrada) y le pone un sombrero a Mártin; /telaviv le
// pone una kipá (solo el disfraz, el estilo no cambia); /normal lo deja como
// siempre (y saca los Mártin de /multi); /multi suma otro Mártin; /edance arma
// una fiesta de 20 segundos; /boom lo hace explotar; /poop se tira un pedo; /67 hace el "six seven". Recargar la página también vuelve todo a la
// normalidad. Los datos y los permisos no cambian.
const IA_COMANDOS=['/edance','/boom','/poop','/67','/pirata','/telaviv','/multi','/normal'];
// svg del disfraz y dónde va [x, y, ancho, alto] en el cuerpo (148x200, el
// tornillo bajado 24 px) y en la cara (96x96, bajada 14 px).
const IA_SOMBREROS={
  pirata:{cuerpo:[23,4,100,48], cara:[10,0,78,37], svg:'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 58">'
    +'<path d="M17 41C19 13 42 4 60 4s41 9 43 37z" fill="#1F1F22"/>'
    +'<path d="M24 36C28 21 42 13 60 13s32 8 36 23" fill="none" stroke="#3A3A40" stroke-width="2"/>'
    +'<path d="M2 37c14-9 32 3 58 3s44-12 58-3c-6 16-30 19-58 19S8 53 2 37z" fill="#2A2A2E" stroke="#C9A227" stroke-width="3" stroke-linejoin="round"/>'
    +'<g stroke="#F4F1E8" stroke-width="3.6" stroke-linecap="round"><path d="M47 22l26 14M73 22L47 36"/></g>'
    +'<circle cx="60" cy="23" r="8.5" fill="#F4F1E8"/><rect x="55" y="27" width="10" height="6" rx="2" fill="#F4F1E8"/>'
    +'<circle cx="56.6" cy="22.5" r="2.3" fill="#1F1F22"/><circle cx="63.4" cy="22.5" r="2.3" fill="#1F1F22"/>'
    +'<path d="M59.2 26.6h1.6l-.8 1.6z" fill="#1F1F22"/></svg>'},
  telaviv:{cuerpo:[50,25,46,19], cara:[29,8,42,17], svg:'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 60 25">'
    +'<path d="M2 22C5 8 17 2 30 2s25 6 28 20c-8 3-18 3-28 3S10 25 2 22z" fill="#1D4E9E" stroke="#163C79" stroke-width="1.5"/>'
    +'<path d="M5 17c7 2.5 16 3.5 25 3.5s18-1 25-3.5" fill="none" stroke="#F4F1E8" stroke-width="2.6"/>'
    +'<path d="M7 13.5c7 2.2 15 3 23 3s16-.8 23-3" fill="none" stroke="#C9A227" stroke-width="1.4" stroke-dasharray="3 2"/>'
    +'<path d="M18 7c3-2 7-3 11-3" fill="none" stroke="#fff" stroke-opacity=".35" stroke-width="2" stroke-linecap="round"/></svg>'}
};
let _iaModo='normal';
const _iaDisfraces={};   // modo -> {m:[cuerpo, habla1, habla2], c:[cara, habla1, habla2]}
// Imagen de Mártin para el modo actual. cuerpo: el tornillo entero (globo);
// si no, la cara (avatar). k: 0 boca cerrada, 1 y 2 frames de habla.
function _iaFoto(cuerpo,k){
  const f=_iaFrunce&&_iaCeños[_iaClaveFotos()];
  return (f?(cuerpo?f.m:f.c):_iaFotosBase(cuerpo))[k||0];
}
// Los tres frames (boca cerrada, habla 1 y 2) del modo actual, sin ceño.
function _iaFotosBase(cuerpo){
  const d=_iaModo!=='normal'&&_iaDisfraces[_iaModo];
  if(d) return cuerpo?d.m:d.c;
  return cuerpo?[IA_MASCOTA,...IA_MASCOTA_HABLA]:[IA_CARA,...IA_CARA_HABLA];
}
function _iaCargarImg(src){
  return new Promise((ok,mal)=>{ const i=new Image(); i.onload=()=>ok(i); i.onerror=mal; i.src=src; });
}
// Dibuja el sombrero sobre cada frame. Al cuerpo le suma lugar arriba para
// que el sombrero no se corte; la cara baja un poco dentro del círculo.
async function _iaDisfrazar(fotos,cuerpo,disfraz){
  const som=await _iaCargarImg('data:image/svg+xml;charset=utf-8,'+encodeURIComponent(disfraz.svg)), [sx,sy,sw,sh]=cuerpo?disfraz.cuerpo:disfraz.cara;
  return Promise.all(fotos.map(async src=>{
    const im=await _iaCargarImg(src), c=document.createElement('canvas'), x=c.getContext('2d');
    if(cuerpo){ c.width=148; c.height=200; x.drawImage(im,0,24); x.drawImage(som,sx,sy,sw,sh); }
    else{ c.width=96; c.height=96; x.fillStyle='#fff'; x.fillRect(0,0,96,96); x.drawImage(im,0,14); x.drawImage(som,sx,sy,sw,sh); }
    return c.toDataURL('image/png');
  }));
}
async function _iaPonerDisfraz(){
  const modo=_iaModo;
  if(modo!=='normal'&&!_iaDisfraces[modo]){
    try{
      const [m,c]=await Promise.all([_iaDisfrazar([IA_MASCOTA,...IA_MASCOTA_HABLA],true,IA_SOMBREROS[modo]),
                                    _iaDisfrazar([IA_CARA,...IA_CARA_HABLA],false,IA_SOMBREROS[modo])]);
      _iaDisfraces[modo]={m,c};
    }catch(e){ return; }
  }
  if(modo===_iaModo) _iaRefrescarFotos();
}
function _iaRefrescarFotos(){
  document.body.classList.toggle('ia-disfrazado',_iaModo!=='normal'&&!!_iaDisfraces[_iaModo]);
  document.querySelectorAll('.ia-av,.ia-p-logo img').forEach(im=>{ im.src=_iaFoto(false); });
  document.querySelectorAll('.ia-globo-m,.ia-hist-vacio img,.ia-clon img').forEach(im=>{ im.src=_iaFoto(true); });
}
// true si el texto era un comando de broma (y ya se resolvió).
function _iaComando(txt){
  const c=txt.trim().toLowerCase();
  if(!IA_COMANDOS.includes(c)) return false;
  if(c==='/edance'){ iaDisco(); return true; }
  if(c==='/poop'){
    const sug=$('ia-p-sug'); if(sug) sug.remove();
    _iaAgregar($('ia-p-msjs'),'u',txt.trim());
    _iaAgregar($('ia-p-msjs'),'a','Perdón… fue el aceite de corte. 😤');
    iaPoop(); return true;
  }
  if(c==='/67'){
    const sug=$('ia-p-sug'); if(sug) sug.remove();
    _iaAgregar($('ia-p-msjs'),'u',txt.trim());
    const m=_iaAgregar($('ia-p-msjs'),'a','Six… seven! 🤷');
    ia67(); _iaHablar('Six seven! Six seven!',m.parentNode.querySelector('.ia-av'));
    return true;
  }
  if(c==='/boom'){
    const sug=$('ia-p-sug'); if(sug) sug.remove();
    _iaAgregar($('ia-p-msjs'),'u',txt.trim());
    _iaAgregar($('ia-p-msjs'),'a','¡BOOM! Tranquilo, ya me volví a armar y la pantalla está sana: era una broma.');
    iaBoom(); return true;
  }
  const box=$('ia-p-msjs'), sug=$('ia-p-sug'); if(sug) sug.remove();
  _iaAgregar(box,'u',txt.trim());
  let msg;
  if(c==='/pirata'){
    _iaModo='pirata';
    msg='¡Ahoy, grumete! Soy el capitán Mártin y este taller es mi barco. Preguntame por el botín de las OT, el stock o los pedidos, que los números te los doy derechitos, por las barbas de Neptuno. Para volver a la normalidad escribí /normal.';
  } else if(c==='/telaviv'){
    _iaModo='telaviv';
    msg='¡Shalom! Me puse la kipá. Sigo siendo el mismo Mártin y los datos del taller te los doy igual de derechitos. Para sacármela escribí /normal.';
  } else if(c==='/multi'){
    msg=iaMulti()?(_iaClones.length===1?'¡Llegó otro Mártin! Hacé clic en él para despedirlo, o escribí /normal.'
                                       :'¡Llegó otro Mártin! Ya somos '+(_iaClones.length+1)+'. Hacé clic en uno para despedirlo, o escribí /normal para que se vayan todos.')
                 :'Ya somos '+(IA_CLONES_MAX+1)+' Mártin, no entramos más. Escribí /normal para que se vayan.';
  } else {
    const habia=_iaModo!=='normal', clones=_iaClones.length, antes=_iaModo;
    _iaModo='normal'; iaMultiSacar();
    msg=habia?'Listo, me saqué '+(antes==='telaviv'?'la kipá':'el disfraz')+'. Volví a ser el Mártin de siempre.'
        :clones?'Listo, los otros Mártin se fueron. Quedé yo solo, el de siempre.':'Ya estoy normal, soy el Mártin de siempre.';
  }
  _iaPonerDisfraz();
  const m=_iaAgregar(box,'a',msg);
  // /multi no habla: se suele mandar muchas veces seguidas y cada audio gasta
  // cupo de voz para cortarse enseguida con el siguiente.
  if(c!=='/multi') _iaHablar(msg,m.parentNode.querySelector('.ia-av'));
  return true;
}

// /multi: aparece otro Mártin que pasea por la pantalla. Clic en uno lo
// despide; /normal o recargar la página los saca a todos.
const IA_CLONES_MAX=8;
const IA_CLON_FRASES=['¡Hola! Soy otro Mártin.','¿Me llamaste?','Dos tornillos piensan mejor que uno.','¡Ajustando tuercas!','Acá ando, de paseo.','¿Quién es el original?'];
let _iaClones=[], _iaClonesRaf=0, _iaClonesT=0;
function iaMulti(){
  if(_iaClones.length>=IA_CLONES_MAX) return false;
  const quieto=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const b=document.createElement('button');
  b.type='button'; b.className='ia-clon'; b.title='Otro Mártin · clic para despedirlo'; b.setAttribute('aria-label','Despedir a este Mártin');
  b.innerHTML='<img alt="">'; b.querySelector('img').src=_iaFoto(true);
  const W=innerWidth-84, H=innerHeight-100, vel=quieto?0:60+Math.random()*60, ang=Math.random()*Math.PI*2;
  const c={el:b,x:Math.random()*Math.max(W,0),y:60+Math.random()*Math.max(H-60,0),vx:Math.cos(ang)*vel,vy:Math.sin(ang)*vel,dice:null};
  b.onclick=()=>_iaClonChau(c);
  document.body.appendChild(b);
  _iaClones.push(c); _iaClonMover(c,0);
  _iaClonDecir(c,IA_CLON_FRASES[Math.floor(Math.random()*IA_CLON_FRASES.length)]);
  if(!_iaClonesRaf&&!quieto){ _iaClonesT=performance.now(); _iaClonesRaf=requestAnimationFrame(_iaClonesPaso); }
  return true;
}
function _iaClonMover(c,dt){
  const W=innerWidth-84, H=innerHeight-100;
  c.x+=c.vx*dt; c.y+=c.vy*dt;
  if(c.x<0){ c.x=0; c.vx=Math.abs(c.vx); } else if(c.x>W){ c.x=Math.max(W,0); c.vx=-Math.abs(c.vx); }
  if(c.y<0){ c.y=0; c.vy=Math.abs(c.vy); } else if(c.y>H){ c.y=Math.max(H,0); c.vy=-Math.abs(c.vy); }
  c.el.style.transform='translate('+c.x+'px,'+c.y+'px)';
  c.el.classList.toggle('izq',c.vx<0);
}
function _iaClonesPaso(t){
  const dt=Math.min((t-_iaClonesT)/1000,0.1); _iaClonesT=t;
  _iaClones.forEach(c=>_iaClonMover(c,dt));
  _iaClonesRaf=_iaClones.length?requestAnimationFrame(_iaClonesPaso):0;
}
function _iaClonDecir(c,txt){
  if(c.dice){ clearTimeout(c.dice.t); c.dice.el.remove(); }
  const d=document.createElement('span'); d.className='ia-clon-dice'; d.textContent=txt; c.el.appendChild(d);
  c.dice={el:d,t:setTimeout(()=>{ d.remove(); c.dice=null; },2500)};
}
function _iaClonChau(c){
  if(c.el.classList.contains('chau')) return;
  _iaClonDecir(c,'¡Chau!');
  c.el.classList.add('chau');
  setTimeout(()=>_iaClonSacar(c),400);
}
function _iaClonSacar(c){
  if(c.dice) clearTimeout(c.dice.t);
  c.el.remove();
  _iaClones=_iaClones.filter(x=>x!==c);
  if(!_iaClones.length&&_iaClonesRaf){ cancelAnimationFrame(_iaClonesRaf); _iaClonesRaf=0; }
}
function iaMultiSacar(){ _iaClones.slice().forEach(_iaClonSacar); }

// /boom: Mártin (y sus clones de /multi) explotan y la pantalla queda
// "rajada". Se arregla con clic, Esc, el botón o sola a los 8 segundos, y
// Mártin vuelve a armarse en su lugar.
const IA_BOOM_MS=8000;
let _iaBoom=null;
function iaBoom(){
  if(_iaBoom) return;
  _iaCallar(); iaDiscoCerrar(); ia67Cerrar();
  if($('ia-panel')&&$('ia-panel').classList.contains('open')) iaAbrirGlobo(false);
  const quieto=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const g=$('ia-globo'), W=innerWidth, H=innerHeight;
  // Puntos de explosión: Mártin (si está a la vista) y cada clone.
  const focos=[];
  if(g&&!g.classList.contains('oculto')){
    const r=g.getBoundingClientRect(); focos.push({x:r.left+r.width/2,y:r.top+r.height/2-14,t:0,grande:true});
    g.classList.add('explotado');
  }
  _iaClones.forEach((c,i)=>focos.push({x:c.x+42,y:c.y+50,t:120+i*90,grande:false}));
  if(!focos.length) focos.push({x:W/2,y:H/2,t:0,grande:true});
  const o=focos[0];
  const ov=document.createElement('div'); ov.className='ia-boom'; ov.setAttribute('role','dialog'); ov.setAttribute('aria-label','Mártin explotó');
  ov.innerHTML='<div class="ia-boom-flash" style="background:radial-gradient(circle at '+o.x+'px '+o.y+'px,#fff 0,#FFE9A8 12%,rgba(255,140,40,.55) 30%,rgba(0,0,0,0) 65%)"></div>'
    +'<canvas></canvas>'+_iaGrietas(focos,W,H)
    +'<button type="button" class="ia-boom-cerrar">'+IA_SVG.x+'Arreglar la pantalla</button>'
    +'<div class="ia-boom-pie">Clic en cualquier lado o Esc para arreglarla</div>';
  document.body.appendChild(ov);
  const st={ov,g,timers:[]};
  _iaBoom=st;
  // Los clones se van con la explosión.
  focos.forEach(f=>{ if(!f.grande) st.timers.push(setTimeout(()=>{ const c=_iaClones.find(c=>Math.abs(c.x+42-f.x)<1&&Math.abs(c.y+50-f.y)<1); if(c) _iaClonSacar(c); },f.t)); });
  st.timers.push(setTimeout(iaMultiSacar,focos.length*90+300));
  ov.addEventListener('click',iaBoomCerrar);
  st.tecla=e=>{ if(e.key==='Escape'){ e.preventDefault(); e.stopImmediatePropagation(); iaBoomCerrar(); } };
  document.addEventListener('keydown',st.tecla,true);
  st.timers.push(setTimeout(iaBoomCerrar,IA_BOOM_MS));
  if(!quieto){ document.body.classList.add('ia-temblor'); st.timers.push(setTimeout(()=>document.body.classList.remove('ia-temblor'),550)); }
  st.parar=_iaBoomParticulas(ov.querySelector('canvas'),focos,quieto);
  st.sonido=_iaBoomSonido(focos);
  ov.querySelector('.ia-boom-cerrar').focus();
}
function iaBoomCerrar(){
  const st=_iaBoom; if(!st) return;
  _iaBoom=null;
  st.timers.forEach(clearTimeout);
  document.removeEventListener('keydown',st.tecla,true);
  document.body.classList.remove('ia-temblor');
  if(st.parar) st.parar();
  if(st.sonido) st.sonido();
  st.ov.remove();
  iaMultiSacar();
  if(st.g&&st.g.classList.contains('explotado')){
    st.g.classList.remove('explotado'); st.g.classList.add('rearmado');
    setTimeout(()=>st.g.classList.remove('rearmado'),600);
  }
}
// Grietas de vidrio: rayos quebrados con ramitas desde cada impacto, anillos
// que los unen y astillas sombreadas cerca del centro.
function _iaGrietas(focos,W,H){
  let h='', tinte='';
  const azar=(a,b)=>a+Math.random()*(b-a), P=q=>q[0].toFixed(1)+' '+q[1].toFixed(1);
  const linea=(d,ancho)=>'<path d="'+d+'" stroke="rgba(0,0,0,.4)" stroke-width="'+(ancho+1.8)+'"/><path d="'+d+'" stroke="rgba(255,255,255,.95)" stroke-width="'+ancho+'"/>';
  focos.forEach((f,fi)=>{
    const n=f.grande?14:8, largo=f.grande?Math.hypot(W,H)*0.75:azar(110,180), anillos=f.grande?[28,70,140,240]:[18,45,80];
    const rayos=[];
    for(let i=0;i<n;i++){
      const ang=i/n*Math.PI*2+azar(-.18,.18), pts=[[f.x,f.y]];
      let r=0;
      while(r<largo){
        r+=azar(16,42); const a=ang+azar(-.09,.09), q=[f.x+Math.cos(a)*r,f.y+Math.sin(a)*r]; pts.push(q);
        if(Math.random()<.22){   // ramita
          let b=a+(Math.random()<.5?-1:1)*azar(.35,.8), rr=0, bp=[q]; const lb=azar(25,f.grande?140:60);
          while(rr<lb){ rr+=azar(10,25); b+=azar(-.15,.15); bp.push([q[0]+Math.cos(b)*rr,q[1]+Math.sin(b)*rr]); }
          h+=linea('M'+bp.map(P).join('L'),.8);
        }
      }
      rayos.push(pts);
    }
    // astillas: entre rayos vecinos, del centro al primer anillo y entre anillos
    const enAnillo=R=>rayos.map(pts=>pts.find(q=>Math.hypot(q[0]-f.x,q[1]-f.y)>=R)||pts[pts.length-1]);
    const capas=anillos.map(enAnillo);
    capas.forEach((cap,k)=>{
      for(let i=0;i<n;i++){
        const a=cap[i], b=cap[(i+1)%n], prev=k?capas[k-1]:null;
        const poly=prev?[prev[i],a,b,prev[(i+1)%n]]:[[f.x,f.y],a,b];
        if(k<2) h+='<path d="M'+poly.map(P).join('L')+'Z" fill="'+((i+k)%2?'rgba(255,255,255,.16)':'rgba(0,0,0,.07)')+'" stroke="none"/>';
        if(Math.random()<.8) h+=linea('M'+P(a)+'L'+P(b),k<2?1.1:.8);
      }
    });
    rayos.forEach(pts=>{ h+=linea('M'+pts.map(P).join('L'),f.grande?1.4:1); });
    h+='<circle cx="'+f.x+'" cy="'+f.y+'" r="'+(f.grande?9:5)+'" fill="rgba(255,255,255,.7)" stroke="rgba(0,0,0,.45)" stroke-width="1.5"/>';
    tinte+='<radialGradient id="ia-gr-t'+fi+'" cx="'+f.x+'" cy="'+f.y+'" r="'+(f.grande?320:120)+'" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#000" stop-opacity=".22"/><stop offset="1" stop-color="#000" stop-opacity="0"/></radialGradient>';
    h='<rect width="'+W+'" height="'+H+'" fill="url(#ia-gr-t'+fi+')" stroke="none"/>'+h;
  });
  return '<svg class="ia-grietas" viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none" fill="none" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true"><defs>'+tinte+'</defs>'+h+'</svg>';
}
// Chispas, pedazos de tornillo y humo. Devuelve la función que la frena.
function _iaBoomParticulas(cv,focos,quieto){
  const dpr=devicePixelRatio||1, W=innerWidth, H=innerHeight;
  cv.width=W*dpr; cv.height=H*dpr;
  const x=cv.getContext('2d'); x.scale(dpr,dpr);
  const ps=[], azar=(a,b)=>a+Math.random()*(b-a), t0=performance.now();
  focos.forEach(f=>{
    const k=f.grande?1:.5;
    for(let i=0;i<(quieto?12:70)*k;i++){ const a=azar(0,Math.PI*2), v=azar(150,650)*k; ps.push({tipo:'chispa',f,x:f.x,y:f.y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-120,vida:azar(.5,1.2),c:['#FFF3B0','#FFD15C','#FF9A3C','#FF5A1F'][i%4]}); }
    for(let i=0;i<(quieto?4:16)*k;i++){ const a=azar(0,Math.PI*2), v=azar(120,420)*k; ps.push({tipo:'pedazo',f,x:f.x,y:f.y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-200,vida:2.2,rot:azar(0,6),vr:azar(-12,12),s:azar(5,12)*(f.grande?1:.7),c:['#9FB7C9','#7C93A6','#C9D6E0','#5E7385'][i%4]}); }
    for(let i=0;i<(quieto?3:10)*k;i++){ const a=azar(0,Math.PI*2), v=azar(20,90); ps.push({tipo:'humo',f,x:f.x,y:f.y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-40,vida:azar(1.4,2.4),r:azar(14,30)*(f.grande?1:.6)}); }
  });
  let raf=0, ult=t0;
  const paso=t=>{
    const dt=Math.min((t-ult)/1000,.05); ult=t;
    x.clearRect(0,0,W,H);
    let vivas=0;
    // bola de fuego que se expande y se apaga
    focos.forEach(f=>{
      const e=((t-t0)-f.t)/1000; if(e<0){ vivas++; return; } if(e>.5) return; vivas++;
      const R=(f.grande?110:55)*Math.sqrt(e/.5)+8, gr=x.createRadialGradient(f.x,f.y,0,f.x,f.y,R);
      gr.addColorStop(0,'rgba(255,255,240,1)'); gr.addColorStop(.3,'rgba(255,214,90,.95)'); gr.addColorStop(.65,'rgba(255,110,30,.7)'); gr.addColorStop(1,'rgba(120,30,10,0)');
      x.globalAlpha=1-e/.5; x.fillStyle=gr; x.beginPath(); x.arc(f.x,f.y,R,0,Math.PI*2); x.fill();
    });
    ps.forEach(p=>{
      const edad=(t-t0)/1000-p.f.t/1000; if(edad<0){ vivas++; return; }
      if(edad>p.vida) return; vivas++;
      const q=1-edad/p.vida;
      p.vy+=(p.tipo==='humo'?-30:700)*dt; p.vx*=p.tipo==='humo'?.98:.995;
      p.x+=p.vx*dt; p.y+=p.vy*dt;
      if(p.tipo==='chispa'){ x.globalAlpha=q; x.strokeStyle=p.c; x.lineWidth=2.4; x.beginPath(); x.moveTo(p.x,p.y); x.lineTo(p.x-p.vx*.03,p.y-p.vy*.03); x.stroke(); }
      else if(p.tipo==='pedazo'){ p.rot+=p.vr*dt; x.globalAlpha=Math.min(1,q*2); x.save(); x.translate(p.x,p.y); x.rotate(p.rot); x.fillStyle=p.c; x.strokeStyle='#2B3A48'; x.lineWidth=1.2; x.beginPath(); x.moveTo(-p.s,-p.s*.5); x.lineTo(p.s*.8,-p.s*.7); x.lineTo(p.s*.6,p.s*.6); x.lineTo(-p.s*.7,p.s*.4); x.closePath(); x.fill(); x.stroke(); x.restore(); }
      else { x.globalAlpha=q*.5; x.fillStyle='#5F5E5A'; x.beginPath(); x.arc(p.x,p.y,p.r*(1.6-q*.6),0,Math.PI*2); x.fill(); }
    });
    x.globalAlpha=1;
    raf=vivas?requestAnimationFrame(paso):0;
  };
  raf=requestAnimationFrame(paso);
  return ()=>{ cancelAnimationFrame(raf); raf=0; };
}
// Estruendo (ruido con filtro que se cierra + golpe grave) y vidrio que se raja.
function _iaBoomSonido(focos){
  const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return null;
  let ctx; try{ ctx=new AC(); }catch(e){ return null; }
  const master=ctx.createGain(); master.gain.value=.6; master.connect(ctx.destination);
  const ruido=ctx.createBuffer(1,Math.floor(ctx.sampleRate*1.6),ctx.sampleRate), d=ruido.getChannelData(0);
  for(let i=0;i<d.length;i++) d[i]=Math.random()*2-1;
  const t0=ctx.currentTime+.02;
  focos.forEach(f=>{
    const t=t0+f.t/1000, v=f.grande?1:.45;
    const s=ctx.createBufferSource(), lp=ctx.createBiquadFilter(), g=ctx.createGain();
    s.buffer=ruido; lp.type='lowpass'; lp.frequency.setValueAtTime(4000,t); lp.frequency.exponentialRampToValueAtTime(120,t+1.2);
    g.gain.setValueAtTime(v,t); g.gain.exponentialRampToValueAtTime(.001,t+1.5);
    s.connect(lp).connect(g).connect(master); s.start(t); s.stop(t+1.6);
    const o=ctx.createOscillator(), og=ctx.createGain();
    o.frequency.setValueAtTime(90,t); o.frequency.exponentialRampToValueAtTime(28,t+.5);
    og.gain.setValueAtTime(v,t); og.gain.exponentialRampToValueAtTime(.001,t+.6);
    o.connect(og).connect(master); o.start(t); o.stop(t+.65);
  });
  // vidrio: chasquidos agudos cortos
  for(let i=0;i<7;i++){
    const t=t0+.25+i*.035+Math.random()*.03;
    const s=ctx.createBufferSource(), hp=ctx.createBiquadFilter(), g=ctx.createGain();
    s.buffer=ruido; hp.type='highpass'; hp.frequency.value=3500+Math.random()*3000;
    g.gain.setValueAtTime(.35,t); g.gain.exponentialRampToValueAtTime(.001,t+.07);
    s.connect(hp).connect(g).connect(master); s.start(t,Math.random()); s.stop(t+.08);
  }
  return ()=>{ try{ master.gain.setTargetAtTime(0,ctx.currentTime,.03); }catch(e){} setTimeout(()=>{ ctx.close().catch(()=>{}); },200); };
}

// /67: Mártin hace el "six seven": las dos manos suben y bajan alternadas con
// un 6 y un 7 encima. Se cierra con clic, Esc, el botón o solo a los 6 s.
const IA_67_MS=6000;
const IA_67_MANO='<svg viewBox="0 0 80 70" xmlns="http://www.w3.org/2000/svg"><g fill="#F2C9A0" stroke="#8A5A3B" stroke-width="3" stroke-linejoin="round">'
  +'<path d="M6 30c10 4 58 4 68 0c2 18-12 34-34 34S4 48 6 30z"/>'
  +'<path d="M10 30c-4-9 2-14 7-10l6 9M24 29c-2-11 5-15 9-9l3 9M38 29c0-11 8-13 10-6l1 7M52 30c2-9 9-10 10-3l-1 6"/></g>'
  +'<path d="M20 44c10 5 30 5 40 0" fill="none" stroke="#C9926A" stroke-width="2.5" stroke-linecap="round"/></svg>';
let _ia67=null;
function ia67(){
  if(_ia67) return;
  iaDiscoCerrar(); iaBoomCerrar();
  const quieto=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const ov=document.createElement('div');
  ov.className='ia-67'; ov.setAttribute('role','dialog'); ov.setAttribute('aria-label','Mártin haciendo el six seven');
  ov.innerHTML='<div class="ia-67-titulo">SIX SEVEN</div>'
    +'<div class="ia-67-escena"><img class="ia-67-martin" alt="">'
    +'<div class="ia-67-mano izq"><b>6</b>'+IA_67_MANO+'</div><div class="ia-67-mano der"><b>7</b>'+IA_67_MANO+'</div></div>'
    +'<button type="button" class="ia-67-cerrar">'+IA_SVG.x+'Cerrar</button>'
    +'<div class="ia-67-pie">Clic en cualquier lado o Esc para salir</div>';
  const img=ov.querySelector('img'); img.src=_iaFoto(true);
  document.body.appendChild(ov);
  const st={ov,img};
  _ia67=st;
  ov.addEventListener('click',ia67Cerrar);
  st.tecla=e=>{ if(e.key==='Escape'){ e.preventDefault(); e.stopImmediatePropagation(); ia67Cerrar(); } };
  document.addEventListener('keydown',st.tecla,true);
  st.fin=setTimeout(ia67Cerrar,IA_67_MS);
  if(!quieto){ let k=0; st.boca=setInterval(()=>{ k=(k+1)%4; img.src=_iaFoto(true,[0,1,2,1][k]); },220); }
  ov.querySelector('.ia-67-cerrar').focus();
}
function ia67Cerrar(){
  const st=_ia67; if(!st) return;
  _ia67=null;
  clearTimeout(st.fin); clearInterval(st.boca);
  document.removeEventListener('keydown',st.tecla,true);
  st.ov.remove();
  const p=$('ia-panel'); if(p&&p.classList.contains('open')) $('ia-p-txt').focus();
}

// /poop: Mártin se tira un pedo (sonido sintetizado y nube verde) y frunce el
// ceño unos segundos: le dibuja cejas enojadas sobre la cara que tenga puesta.
const IA_CEJAS={cuerpo:[[50,24,70,33],[80,31,101,21]], cara:[[24,19,46,29],[58,27,82,14]]};
const IA_POOP_MS=3000;
let _iaFrunce=false, _iaPoop=null;
const _iaCeños={};   // modo (o 'normal') -> {m:[...], c:[...]}
function _iaClaveFotos(){ return _iaModo!=='normal'&&_iaDisfraces[_iaModo]?_iaModo:'normal'; }
async function _iaConCeño(fotos,cuerpo,disfrazado){
  const dy=disfrazado?(cuerpo?24:14):0;
  return Promise.all(fotos.map(async src=>{
    const im=await _iaCargarImg(src), c=document.createElement('canvas'), x=c.getContext('2d');
    c.width=im.width; c.height=im.height; x.drawImage(im,0,0);
    x.lineCap='round';
    // borde claro para que se vean también sobre el ala de un sombrero oscuro
    [['rgba(255,255,255,.85)',8],['#26323C',5]].forEach(([color,ancho])=>{
      x.strokeStyle=color; x.lineWidth=ancho;
      (cuerpo?IA_CEJAS.cuerpo:IA_CEJAS.cara).forEach(([x1,y1,x2,y2])=>{ x.beginPath(); x.moveTo(x1,y1+dy); x.lineTo(x2,y2+dy); x.stroke(); });
    });
    return c.toDataURL('image/png');
  }));
}
async function _iaPrepararCeño(){
  const clave=_iaClaveFotos();
  if(!_iaCeños[clave]){
    const dis=clave!=='normal';
    const [m,c]=await Promise.all([_iaConCeño(_iaFotosBase(true),true,dis),_iaConCeño(_iaFotosBase(false),false,dis)]);
    _iaCeños[clave]={m,c};
  }
}
async function iaPoop(){
  if(_iaPoop) return;
  const st={timers:[],nube:null,sonido:null}; _iaPoop=st;
  _iaCallar();
  try{ await _iaPrepararCeño(); }catch(e){}
  if(_iaPoop!==st) return;
  // La nube sale de la punta del tornillo (o de la cara del panel si está abierto).
  const p=$('ia-panel'), g=$('ia-globo');
  let x=innerWidth-60, y=innerHeight-30;
  if(p&&p.classList.contains('open')){ const r=p.querySelector('.ia-p-logo').getBoundingClientRect(); x=r.left+r.width/2; y=r.bottom; }
  else if(g&&!g.classList.contains('oculto')){ const r=g.querySelector('.ia-globo-m').getBoundingClientRect(); x=r.left+r.width/2; y=r.bottom-6; g.classList.add('pedo'); }
  const n=document.createElement('div'); n.className='ia-pedo'; n.style.left=x+'px'; n.style.top=y+'px';
  let h='';
  for(let i=0;i<9;i++){
    const a=Math.PI*(.15+Math.random()*.7), d=40+Math.random()*70;
    h+='<i style="--dx:'+(Math.cos(a)*d*(Math.random()<.5?-1:1)).toFixed(0)+'px;--dy:'+(-Math.sin(a)*d*.6+10).toFixed(0)+'px;--s:'+(1.4+Math.random()*1.4).toFixed(2)+';animation-delay:'+(i*.05).toFixed(2)+'s"></i>';
  }
  h+='<svg viewBox="0 0 60 60" fill="none" stroke="#7A9A2A" stroke-width="3" stroke-linecap="round"><path d="M14 58c-6-8 6-12 0-20s6-12 0-20"/><path d="M30 54c-6-8 6-12 0-20s6-12 0-20"/><path d="M46 58c-6-8 6-12 0-20s6-12 0-20"/></svg>';
  n.innerHTML=h; document.body.appendChild(n); st.nube=n;
  _iaFrunce=true; _iaRefrescarFotos();
  st.sonido=_iaPedoSonido();
  st.timers.push(setTimeout(()=>{ if(g) g.classList.remove('pedo'); },600));
  st.timers.push(setTimeout(iaPoopFin,IA_POOP_MS));
}
function iaPoopFin(){
  const st=_iaPoop; if(!st) return;
  _iaPoop=null;
  st.timers.forEach(clearTimeout);
  if(st.nube) st.nube.remove();
  if(st.sonido) st.sonido();
  const g=$('ia-globo'); if(g) g.classList.remove('pedo');
  if(_iaFrunce){ _iaFrunce=false; _iaRefrescarFotos(); }
}
// Tono grave que tiembla (sierra con vibrato y trémolo) más un soplido de ruido.
function _iaPedoSonido(){
  const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return null;
  let ctx; try{ ctx=new AC(); }catch(e){ return null; }
  const t=ctx.currentTime+.02, dur=.85+Math.random()*.3;
  const master=ctx.createGain(); master.gain.value=.7; master.connect(ctx.destination);
  const env=ctx.createGain();
  env.gain.setValueAtTime(.0001,t); env.gain.exponentialRampToValueAtTime(1,t+.04);
  env.gain.setValueAtTime(1,t+dur*.65); env.gain.exponentialRampToValueAtTime(.001,t+dur);
  env.connect(master);
  const o=ctx.createOscillator(); o.type='sawtooth';
  o.frequency.setValueAtTime(90,t); o.frequency.linearRampToValueAtTime(125,t+dur*.3); o.frequency.linearRampToValueAtTime(65,t+dur);
  const vib=ctx.createOscillator(), vg=ctx.createGain(); vib.frequency.value=26; vg.gain.value=30; vib.connect(vg).connect(o.frequency);
  const trem=ctx.createGain(); trem.gain.value=.6;
  const tl=ctx.createOscillator(), tg=ctx.createGain(); tl.frequency.value=15; tg.gain.value=.4; tl.connect(tg).connect(trem.gain);
  const lp=ctx.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=650; lp.Q.value=5;
  o.connect(lp).connect(trem).connect(env);
  const ruido=ctx.createBuffer(1,Math.floor(ctx.sampleRate*(dur+.1)),ctx.sampleRate), d=ruido.getChannelData(0);
  for(let i=0;i<d.length;i++) d[i]=Math.random()*2-1;
  const s=ctx.createBufferSource(), bp=ctx.createBiquadFilter(), sg=ctx.createGain();
  s.buffer=ruido; bp.type='bandpass'; bp.frequency.value=260; bp.Q.value=1.2; sg.gain.value=.35;
  s.connect(bp).connect(sg).connect(env);
  [o,vib,tl,s].forEach(n=>{ n.start(t); n.stop(t+dur+.05); });
  const fin=setTimeout(()=>{ ctx.close().catch(()=>{}); },(dur+.3)*1000);
  return ()=>{ clearTimeout(fin); try{ master.gain.setTargetAtTime(0,ctx.currentTime,.03); }catch(e){} setTimeout(()=>{ ctx.close().catch(()=>{}); },200); };
}

// /edance: overlay con luces, bola disco, Mártin gigante bailando y un loop
// disco sintetizado. Se cierra con clic, Esc, el botón o solo a los 20 s.
const IA_DISCO_MS=20000;
let _iaDisco=null;
function _iaBolaDisco(){
  const tonos=['#E8EEF5','#B9C6D6','#8FA0B5','#FFFFFF','#6D7F96','#D3DCE8','#A6B5C9','#FF9ADF','#9AEBFF'];
  let f='';
  for(let r=0;r<14;r++) for(let j=0;j<21;j++){
    const t=tonos[(r*5+(j%6)*7+(r*(j%6))%4)%tonos.length];
    f+='<rect x="'+(18+j*12)+'" y="'+(68+r*12)+'" width="11" height="11" fill="'+t+'"/>';
  }
  const brillo=(x,y,s,d)=>'<path class="ia-bola-brillo" style="animation-delay:'+d+'s" d="M'+x+' '+(y-s)+'Q'+x+' '+y+' '+(x+s)+' '+y+'Q'+x+' '+y+' '+x+' '+(y+s)+'Q'+x+' '+y+' '+(x-s)+' '+y+'Q'+x+' '+y+' '+x+' '+(y-s)+'z" fill="#fff"/>';
  return '<svg viewBox="0 0 200 250" aria-hidden="true"><defs>'
    +'<clipPath id="ia-bola-clip"><circle cx="100" cy="150" r="80"/></clipPath>'
    +'<radialGradient id="ia-bola-luz" cx="35%" cy="30%" r="75%"><stop offset="0" stop-color="#fff" stop-opacity=".55"/><stop offset=".45" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".5"/></radialGradient></defs>'
    +'<line x1="100" y1="0" x2="100" y2="66" stroke="#C8CDD4" stroke-width="2"/><rect x="92" y="62" width="16" height="10" rx="2" fill="#9AA4B2"/>'
    +'<circle cx="100" cy="150" r="80" fill="#3B4656"/>'
    +'<g clip-path="url(#ia-bola-clip)"><g class="ia-bola-facetas">'+f+'</g></g>'
    +'<circle cx="100" cy="150" r="80" fill="url(#ia-bola-luz)"/>'
    +brillo(70,112,13,0)+brillo(138,170,10,.5)+brillo(112,96,7,.9)+brillo(62,190,8,1.2)+'</svg>';
}
function iaDisco(){
  if(_iaDisco) return;
  _iaCallar(); ia67Cerrar();
  const quieto=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const ov=document.createElement('div');
  ov.className='ia-disco'+(quieto?' quieto':''); ov.setAttribute('role','dialog'); ov.setAttribute('aria-label','Mártin bailando');
  ov.innerHTML='<div class="ia-disco-luces"><i></i><i></i><i></i><i></i><i></i></div>'
    +'<div class="ia-disco-bola">'+_iaBolaDisco()+'</div>'
    +'<div class="ia-disco-baila"><div class="ia-disco-gira"><img class="ia-disco-martin" alt=""></div></div>'
    +'<button type="button" class="ia-disco-cerrar">'+IA_SVG.x+'Cerrar y parar la música</button>'
    +'<div class="ia-disco-pie">Clic en cualquier lado o Esc para salir</div>';
  const img=ov.querySelector('img'); img.src=_iaFoto(true);
  document.body.appendChild(ov);
  const st={ov,img};
  _iaDisco=st;
  ov.addEventListener('click',iaDiscoCerrar);
  // En captura: el Esc cierra la fiesta y no llega al chat ni a los modales.
  st.tecla=e=>{ if(e.key==='Escape'){ e.preventDefault(); e.stopImmediatePropagation(); iaDiscoCerrar(); } };
  document.addEventListener('keydown',st.tecla,true);
  st.fin=setTimeout(iaDiscoCerrar,IA_DISCO_MS);
  if(!quieto){ let k=0; st.boca=setInterval(()=>{ k=(k+1)%4; img.src=_iaFoto(true,[0,1,2,1][k]); },250); }
  st.musica=_iaMusicaDisco();
  ov.querySelector('.ia-disco-cerrar').focus();
}
function iaDiscoCerrar(){
  const st=_iaDisco; if(!st) return;
  _iaDisco=null;
  clearTimeout(st.fin); clearInterval(st.boca);
  document.removeEventListener('keydown',st.tecla,true);
  if(st.musica) st.musica();
  st.ov.remove();
  const p=$('ia-panel'); if(p&&p.classList.contains('open')) $('ia-p-txt').focus();
}
// Loop disco a 120 BPM con Web Audio: bombo en negras, hi-hat, bajo de
// octavas y un arpegio sobre La m, Fa, Do y Sol. Devuelve la función que lo para.
function _iaMusicaDisco(){
  const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return null;
  let ctx; try{ ctx=new AC(); }catch(e){ return null; }
  const master=ctx.createGain(); master.gain.value=0; master.connect(ctx.destination);
  master.gain.setTargetAtTime(0.4,ctx.currentTime,0.08);
  const ruido=ctx.createBuffer(1,Math.floor(ctx.sampleRate*0.2),ctx.sampleRate), dat=ruido.getChannelData(0);
  for(let i=0;i<dat.length;i++) dat[i]=Math.random()*2-1;
  const PASO=60/120/4, nota=n=>440*Math.pow(2,(n-69)/12);
  const ACORDES=[[57,60,64],[53,57,60],[48,52,55],[55,59,62]];
  const bombo=t=>{
    const o=ctx.createOscillator(), g=ctx.createGain();
    o.frequency.setValueAtTime(150,t); o.frequency.exponentialRampToValueAtTime(42,t+0.12);
    g.gain.setValueAtTime(0.9,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.3);
    o.connect(g).connect(master); o.start(t); o.stop(t+0.32);
  };
  const hihat=(t,v)=>{
    const s=ctx.createBufferSource(), f=ctx.createBiquadFilter(), g=ctx.createGain();
    s.buffer=ruido; f.type='highpass'; f.frequency.value=7000;
    g.gain.setValueAtTime(v,t); g.gain.exponentialRampToValueAtTime(0.001,t+0.05);
    s.connect(f).connect(g).connect(master); s.start(t); s.stop(t+0.06);
  };
  const tono=(t,frec,dur,tipo,v,corte)=>{
    const o=ctx.createOscillator(), f=ctx.createBiquadFilter(), g=ctx.createGain();
    o.type=tipo; o.frequency.value=frec; f.type='lowpass'; f.frequency.value=corte;
    g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(v,t+0.01); g.gain.exponentialRampToValueAtTime(0.001,t+dur);
    o.connect(f).connect(g).connect(master); o.start(t); o.stop(t+dur+0.02);
  };
  let sig=ctx.currentTime+0.06, k=0;
  const programar=()=>{
    while(sig<ctx.currentTime+0.15){
      const s=k%16, ac=ACORDES[Math.floor(k/16)%4];
      if(s%4===0) bombo(sig);
      hihat(sig,s%4===2?0.3:0.07);
      if(s%2===0) tono(sig,nota(ac[0]-24+(s%4===2?12:0)),PASO*1.7,'sawtooth',0.25,900);
      tono(sig,nota(ac[s%3]+12+(s>=8?12:0)),PASO*0.9,'square',0.045,3200);
      sig+=PASO; k++;
    }
  };
  programar();
  const iv=setInterval(programar,25);
  if(ctx.state!=='running') ctx.resume().catch(()=>{});
  return ()=>{
    clearInterval(iv);
    try{ master.gain.setTargetAtTime(0,ctx.currentTime,0.03); }catch(e){}
    setTimeout(()=>{ ctx.close().catch(()=>{}); },200);
  };
}

