function setupRoles(){
 if(ROL==='admin'){ $('nav-usr').style.display='block'; $('nav-aud').style.display='block'; $('nav-cam').style.display='block'; $('nav-tab').style.display='block'; }
 if(IA_PERMITIDA){ $('nav-ia').style.display='block'; iaIniciarGlobo(); }
 
  // Apply module permissions to sidebar nav items
  // Admin always sees everything; other roles respect PERMS
  if(ROL !== 'admin'){
    document.querySelectorAll('.ni[data-p]').forEach(function(ni){
      const mod = ni.getAttribute('data-p');
      if(mod === 'ia') return;   // el asistente va por su propio permiso (IA_PERMITIDA)
      if(ROL === 'logistica'){
        // Logistica: ocultar todo salvo lo que tenga permiso explícito '1'
        if(PERMS['mod_'+mod] !== '1') ni.style.display = 'none';
      } else {
        // Otros roles: ocultar solo si el permiso está explícitamente en '0'
        if(PERMS['mod_'+mod] === '0') ni.style.display = 'none';
      }
    });
  }

  // Hide section labels that have no visible children
  document.querySelectorAll('.sl').forEach(function(sl){
    let next = sl.nextElementSibling;
    let hasVisible = false;
    while(next && !next.classList.contains('sl')){
      if(next.style.display !== 'none' && next.id !== 'nav-usr' && next.id !== 'nav-aud' && next.id !== 'nav-cam' && next.id !== 'nav-tab') hasVisible = true;
      next = next.nextElementSibling;
    }
    if(!hasVisible) sl.style.display = 'none';
  });

  // Original role-based action buttons
  [['b-ot',['admin','operario','vendedor']],['b-prod',['admin','operario']],
   ['b-maq',['admin','operario']],['b-mant',['admin','operario']],['mant-b-real',['admin','operario']],['b-tkt',['admin','operario']],
   ['b-mat',['admin','almacen','operario','logistica']],['b-prov',['admin','almacen','vendedor']],
   ['b-ott-nueva',['admin','operario']],['b-recepcion',['admin','almacen']],['b-rec-oc',['admin','almacen','vendedor']],
   ['b-pres',['admin','vendedor']],['pres-b-edit',['admin','vendedor']],['b-cli',['admin','vendedor']],
   ['b-pcot',['admin','vendedor']]].forEach(([id,roles])=>{
    const el=$(id);if(el&&roles.includes(ROL))el.style.display='';
  });
  if(ROL==='admin'){const be=$('b-emp');if(be)be.style.display='';}
  if(['admin','operario'].includes(ROL)){
    const el=$('b-nov');if(el)el.style.display='inline-block';
  }
  if(['admin','operario','vendedor'].includes(ROL)){
    const el=$('b-sc');if(el)el.dataset.permitido='1';
  }
  if(['admin','almacen','vendedor'].includes(ROL)){const el=$('b-oc');if(el)el.dataset.permitido='1';}
  if(['admin','vendedor'].includes(ROL)){const el=$('b-occ');if(el)el.style.display='inline-flex';}
  if(['admin','almacen','vendedor'].includes(ROL)){const el=$('b-cot');if(el)el.dataset.permitido='1';}
  // Compras arranca en Solicitudes: deja visible solo el botón de esa vista.
  if(typeof mostrarVistaCompras==='function') mostrarVistaCompras(compView||'solicitudes');
  if(['admin','almacen'].includes(ROL)){const el=$('b-lote');if(el)el.style.display='inline-block';}

  // El Dashboard Económico/Financiero es monetario de punta a punta: sin el
  // permiso su API responde 403, así que tampoco se ofrece en el menú.
  if(!VER_MONETARIO){
    var _niEco = document.querySelector('.ni[data-p="dash_economico"]');
    if(_niEco) _niEco.remove();
    var _pgEco = document.getElementById('p-dash_economico');
    if(_pgEco) _pgEco.remove();
  }
  // (Las clases .col-monetario/.metric-monetario no existían en ningún markup:
  // el bloque que las ocultaba era código muerto. Lo monetario estático se
  // marca ahora con data-monetario y se ELIMINA, no se oculta.)
  // Ocultar campos monetarios del formulario de producto para operario
  if(ROL==='operario'){
    ['prod-cm-wrap','prod-cmo-wrap','prod-pv-wrap'].forEach(function(id){
      var el=document.getElementById(id);
      if(el) el.style.display='none';
    });
  }
  // Campos de entrada monetarios: se ELIMINAN del formulario. Ocultarlos
  // dejaba el input en el DOM, con su valor real legible desde el inspector
  // y enviándose igual al guardar.
  if(!VER_MONETARIO){
    ['ot-cm','op-prec','ope-precio','mat-pre','emat-pre','ottn-precio','ope-prec',
     'rec-precio','lm-pre','prod-cm','prod-cmo','prod-pv','ott-precio-val',
     'tkt-cos','cot-pre','cfg-valor-hora-mo','oc-precio','occ-precio',
     'pres-subtotal','pres-iva'].forEach(function(id){
      var el=document.getElementById(id);
      if(!el) return;
      var cont=el.closest('.fg')||el.closest('[id$="-wrap"]')||el;
      _registrarMonBorrado(cont);
      cont.remove();
    });
  }
  // Precio unitario en editar material: solo visible para admin y logistica
  if(ROL!=='admin'){
    var epw=document.getElementById('emat-pre-wrap');
    if(epw) epw.style.display='none';
  }

  // Logistica: en Compras, solo debe ver "Solicitudes" y "OC emitidas"
  // (ocultar tab "Cotizaciones"), y no debe ver el botón "+ Nueva OC"
  if(ROL==='logistica'){
    var tabCot=document.querySelector('#comp-tabs .tab[data-cv="cotizaciones"]');
    if(tabCot) tabCot.style.display='none';
    var boc=$('b-oc');
    if(boc) boc.style.display='none';
  }
}

